<section class="page-header"><div><span class="eyebrow">Personal workspace</span><h1>Favourites & Recent Records</h1><p>Return quickly to the CRM records most relevant to your work.</p></div></section><div class="dashboard-grid"><section class="panel span-2"><div class="panel-head"><div><h2>Favourites</h2><p>Records you explicitly starred</p></div></div><div class="compact-list"><?php foreach($favourites as $item):?><a class="list-row" href="<?= url($item['entity'].'/'.$item['id']) ?>"><span class="list-icon"><i class="fa-solid <?= e($item['icon']) ?>"></i></span><span class="list-main"><strong><?= e($item['title']) ?></strong><small><?= e($item['module']) ?></small></span><i class="fa-solid fa-star text-warning"></i></a><?php endforeach;?><?php if(!$favourites):?><div class="empty-inline">Star a lead, client, project, task or other record to keep it here.</div><?php endif;?></div></section><section class="panel span-2"><div class="panel-head"><div><h2>Recently viewed</h2><p>Your latest permission-checked records</p></div></div><div class="compact-list"><?php foreach($recent as $item):?><a class="list-row" href="<?= url($item['entity'].'/'.$item['id']) ?>"><span class="list-icon"><i class="fa-solid <?= e($item['icon']) ?>"></i></span><span class="list-main"><strong><?= e($item['title']) ?></strong><small><?= e($item['module']) ?></small></span><span class="list-date"><?= e(date('d M, g:i A',strtotime($item['moment']))) ?></span></a><?php endforeach;?><?php if(!$recent):?><div class="empty-inline">Viewed records will appear here.</div><?php endif;?></div></section></div>
